INSERT INTO products (id, title, description, type, price_cents, currency, artwork, preview, tags, release_id, metadata, featured, published, max_quantity, catalog_hash, created_at, updated_at) VALUES ('sample-pack-vol1', 'Frayed Signals — Sample Pack Vol. 1', '300+ one-shots, glitch loops, bit-crushed vocal chops and stitched-together drum fills. WAV, 24-bit.', 'sample-pack', 2499, 'USD', NULL, NULL, '["wav","one-shots","loops"]', NULL, '{"hue":300}', 1, 0, 1, 'a39036b4cee58749', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, description = excluded.description, type = excluded.type, price_cents = excluded.price_cents, currency = excluded.currency, artwork = excluded.artwork, preview = excluded.preview, tags = excluded.tags, release_id = excluded.release_id, metadata = excluded.metadata, featured = excluded.featured, published = excluded.published, max_quantity = excluded.max_quantity, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE products.catalog_hash IS NOT excluded.catalog_hash OR products.deleted_at IS NOT NULL;
